class Reassembler:
    def __init__(self):
        self.buffer = bytearray()
        self.state = 0
        self.frame_length = 0
        self.payload_xor = 0
        self.payload_bytes = bytearray()

    def feed(self, chunk):
        result = []
        self.buffer.extend(chunk)
        i = 0
        n = len(self.buffer)

        while i < n:
            if self.state == 0:
                if i + 1 >= n:
                    break
                if self.buffer[i] == 0xAA and self.buffer[i + 1] == 0x55:
                    self.state = 1
                    i += 2
                else:
                    i += 1
            elif self.state == 1:
                if i + 1 >= n:
                    break
                self.frame_length = self.buffer[i] | (self.buffer[i + 1] << 8)
                i += 2
                if self.frame_length > 4096:
                    self.state = 0
                    self.payload_bytes = bytearray()
                else:
                    self.state = 2
                    self.payload_xor = 0
                    self.payload_bytes = bytearray()
            elif self.state == 2:
                needed = self.frame_length - len(self.payload_bytes)
                if i + needed > n:
                    break
                self.payload_bytes.extend(self.buffer[i:i + needed])
                for b in self.buffer[i:i + needed]:
                    self.payload_xor ^= b
                i += needed
                self.state = 3
            elif self.state == 3:
                if i >= n:
                    break
                check_byte = self.buffer[i]
                i += 1
                if check_byte == self.payload_xor:
                    result.append(bytes(self.payload_bytes))
                self.state = 0
                self.payload_bytes = bytearray()
        self.buffer = self.buffer[i:]
        return result
